/** Greenhouse Daily Control: presentation of Finance/Harvest/Work authorities only. */
import {e,link,Header,icon} from './components.js';
import {harvestNumber,chartHeight} from './harvest-connected.js';
import {financeAmount,financeSourceLinks} from './finance-connected.js';
const tabs={overview:'Обзор',harvest:'Урожай',finance:'Финансы',work:'Работы'};
const metrics={branches:'Ветки',kg:'Килограммы',revenue:'Выручка'};
const iso=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')&&!Number.isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;
export function greenhouseSelection(route,today){
 const [,id='all',tab='overview',from='',to='',currency='TRY',allocation='all',month='all',metric='kg']=route.split('/'),[year,m]=today.split('-').map(Number);
 return {greenhouse_id:id==='all'?null:id,tab:Object.hasOwn(tabs,tab)?tab:'overview',date_from:iso(from)?from:`${year-(m<10?1:0)}-10-01`,date_to:iso(to)?to:today,currency:['TRY','USD','EUR','UAH'].includes(currency)?currency:'TRY',allocation:['all','exact','estimated'].includes(allocation)?allocation:'all',month:/^\d{4}-(0[1-9]|1[0-2])$/.test(month)?month:null,metric:Object.hasOwn(metrics,metric)?metric:'kg'};
}
export function greenhouseRoute(f,changes={}){const x={...f,...changes};return `greenhouses/${x.greenhouse_id||'all'}/${x.tab}/${x.date_from}/${x.date_to}/${x.currency}/${x.allocation}/${x.month||'all'}/${x.metric}`;}
export function greenhouseQuery(f){const p=new URLSearchParams({date_from:f.date_from,date_to:f.date_to,currency:f.currency,allocation:f.allocation});if(f.greenhouse_id)p.set('greenhouse_id',f.greenhouse_id);return p.toString();}
export function greenhouseBackRoute(encoded){try{const route=decodeURIComponent(encoded||'');return /^greenhouses\/(all|[0-9a-f-]{36})\/(overview|harvest|finance|work)\/\d{4}-\d{2}-\d{2}\/\d{4}-\d{2}-\d{2}\/(TRY|USD|EUR|UAH)\/(all|exact|estimated)\/(all|\d{4}-\d{2})\/(branches|kg|revenue)$/.test(route)?route:null;}catch{return null;}}
const card=body=>`<section class="card greenhouse-card">${body}</section>`;
const note=text=>`<p class="note">${e(text)}</p>`;
const row=(label,value,sub='')=>`<div class="greenhouse-fact"><div><span>${e(label)}</span>${sub?`<small>${e(sub)}</small>`:''}</div><strong>${e(value)}</strong></div>`;
const measure=(v,unit)=>v==null?'Неизвестно':`${harvestNumber(v)} ${unit}`;
const coverage=m=>m?.classification==='NO_DATA'||m?.source_count===0?'Нет источников':`${m?.source_count??0} источников${m?.missing_count?' · неполные данные':''}`;
const classification=v=>({EXACT:'Точно',ESTIMATED:'Есть оценка',PARTIAL:'Неполные данные',UNAVAILABLE:'Неизвестно',NO_DATA:'Нет источников',ESTIMATED_DENOMINATOR:'Оценочный знаменатель'})[v]||'Основание требует проверки';
const eventLink=(label,kind,id,f,cls='list-row')=>link(label,`${kind}/${id}/${encodeURIComponent(greenhouseRoute(f))}`,cls);
export function greenhouseHarvestEvents(harvest,selection){
 const events=selection.metric==='branches'?harvest.field_events||[]:harvest.events||[];
 return events.filter(event=>event.event_date>=selection.date_from&&event.event_date<=selection.date_to&&(!selection.month||event.event_date.startsWith(selection.month))&&(selection.metric!=='revenue'||event.currency===selection.currency));
}
export function greenhouseRequestGroups(requests,greenhouseId,selection){
 const scoped=requests.filter(request=>request.greenhouse_id===greenhouseId);
 return {period:scoped.filter(request=>{const day=request.current_plan?.start_date;return day&&day>=selection.date_from&&day<=selection.date_to;}),undated:scoped.filter(request=>!request.current_plan?.start_date)};
}
export function greenhouseAttention(work){
 const day=work?.day_workers||{};
 return {task_count:work?.attention?.length??0,undated_request_count:day.undated_request_ids?.length??0,undated_attention_count:Array.isArray(day.undated_attention_request_ids)?day.undated_attention_request_ids.length:null};
}
function attentionRows(work){const counts=greenhouseAttention(work);return row('Поручения: нужно внимание',String(counts.task_count))+row('Заявки без даты: нужно внимание',counts.undated_attention_count==null?'Неизвестно':String(counts.undated_attention_count),counts.undated_request_count?'Всего заявок без даты: '+counts.undated_request_count+'. В итоги выбранного периода не включены.':'');}

export function greenhouseFilters(result,f){return `<form data-form="greenhouse-filters" class="greenhouse-filters"><label>Теплица<select name="greenhouse_id"><option value="">Все теплицы</option>${result.greenhouses.map(g=>`<option value="${e(g.id)}" ${g.id===f.greenhouse_id?'selected':''}>${e(g.name)}</option>`).join('')}</select></label><label>С даты<input type="date" name="date_from" value="${e(f.date_from)}" required></label><label>По дату включительно<input type="date" name="date_to" value="${e(f.date_to)}" required></label><label>Валюта<select name="currency">${['TRY','USD','EUR','UAH'].map(c=>`<option ${c===f.currency?'selected':''}>${c}</option>`).join('')}</select></label><label>Основание урожая<select name="allocation">${[['all','Все данные'],['exact','Точно'],['estimated','Оценка']].map(([v,n])=>`<option value="${v}" ${f.allocation===v?'selected':''}>${n}</option>`).join('')}</select></label><button type="submit" class="btn secondary">Показать</button><div class="form-error" role="alert"></div></form>`;}
function areaView(area){return row('Проверенная площадь',measure(area?.area_da,'дёнюм'),area?.status==='VERIFIED_FULL_PERIOD'?`Версии действуют ${area.validity_from} — ${area.validity_to}`:area?.status==='CHANGED_IN_PERIOD'?'Площадь изменилась в периоде. Показатели на дёнюм недоступны.':'Площадь не подтверждена на весь период. Показатели на дёнюм неизвестны.');}
function overview(g,f){const h=g.harvest,x=g.finance,w=g.work.day_workers||{};return `<div class="greenhouse-grid">${card(`<h2>Урожай периода</h2>${row('Ветки · полевые отчёты',measure(h.branches.value,'веток'),coverage(h.branches))}${row('Вес · подтверждённое депо',measure(h.depot_kg.value,'кг'),classification(h.depot_kg.classification))}${row('Средневзвешенная цена',financeAmount(h.weighted_price_per_kg,f.currency+'/кг'),'По весу документов в выбранной валюте')}${link('Месяцы и источники',greenhouseRoute(f,{tab:'harvest'}),'section-link')}`)}${card(`<h2>Финансы периода</h2>${row('Выручка',financeAmount(x.revenue,f.currency))}${row('Учтённые затраты',financeAmount(x.operating_cost,f.currency))}${row('Результат известной части',financeAmount(x.operating_result,f.currency))}${note('Это не полная себестоимость. Начисление и оплата не считаются дважды.')}${link('Затраты и источники',greenhouseRoute(f,{tab:'finance'}),'section-link')}`)}${card(`<h2>Работы</h2>${attentionRows(g.work)}${row('Сообщено полных человеко-дней',harvestNumber(w.reported_people_days))}${row('Принято владельцем, человеко-дней',harvestNumber(w.confirmed_people_days))}${link('Планы, факты и расчёты',greenhouseRoute(f,{tab:'work'}),'section-link')}`)}${card(`<h2>Площадь и сопоставление</h2>${areaView(g.area)}${row('Выручка на дёнюм',financeAmount(x.per_da?.revenue,f.currency+'/дёнюм'))}${row('Затраты на дёнюм',financeAmount(x.per_da?.operating_cost,f.currency+'/дёнюм'))}${comparison(g.comparison,f)}`)}</div>`;}
function comparison(c,f){if(c?.status!=='AVAILABLE')return note(c?.status==='NO_PRIOR_SOURCES'?'Сопоставимого прошлого сезона нет: подтверждённых источников недостаточно.':'Сравнение с прошлым сезоном недоступно для этого периода.');return `<details><summary>Сопоставимые прошедшие дни сезона</summary>${note(`Текущий: ${c.current_date_from} — ${c.current_date_to}. Предыдущий: ${c.date_from} — ${c.date_to}. Используются текущие действующие источники.`)}${row('Выручка · текущий / прошлый',`${financeAmount(c.current.revenue,f.currency)} / ${financeAmount(c.previous.revenue,f.currency)}`)}${row('Вес депо · текущий / прошлый',`${measure(c.current.depot_kg?.value,'кг')} / ${measure(c.previous.depot_kg?.value,'кг')}`)}</details>`;}
function monthValue(month,metric){return metric==='branches'?month.branches?.value:metric==='revenue'?month.revenue:month.depot_kg;}
export function greenhouseMonthCoverage(month,metric){
 if(metric==='branches')return coverage(month.branches||{});
 if(month.state==='NO_DATA'||month.source_count===0)return 'Нет источников';
 if(month.state==='UNKNOWN')return 'Принадлежность теплице неизвестна';
 if(month.state==='PARTIAL'||month.missing_source_count>0)return `Неполные данные: известно ${month.known_source_count??0} из ${month.source_count??0} источников`;
 return `Источников: ${month.source_count??0}`;
}
export function greenhouseEventValue(event,selection){
 if(selection.metric==='branches')return measure(event.cut_count,'веток');
 if(event.selected_attribution_known===false)return 'Принадлежность теплице неизвестна · не включено в итог';
 return selection.metric==='revenue'?financeAmount(event.selected_amount,event.currency):measure(event.selected_kg,'кг');
}

function harvest(g,f){const h=g.harvest,unit=f.metric==='branches'?'веток':f.metric==='revenue'?f.currency:'кг',months=h.months||[],positive=months.map(m=>monthValue(m,f.metric)).filter(v=>v!=null),maximum=positive.reduce((a,b)=>chartHeight(a,b)>=100?a:b,'0');const selected=months.find(m=>m.month===f.month),events=greenhouseHarvestEvents(h,f);
 return `<nav class="greenhouse-tabs" aria-label="Показатель урожая">${Object.entries(metrics).map(([key,label])=>link(label,greenhouseRoute(f,{metric:key}),f.metric===key?'active':'' )).join('')}</nav>`+card(`<h2>Месяцы выбранного периода</h2><div class="harvest-month-chart">${months.map(m=>{const value=monthValue(m,f.metric);return link(`<span class="harvest-bar-track"><span class="harvest-bar bar-h-${Math.round(chartHeight(value,maximum))}"></span>${value==null?'<span class="harvest-no-data">—</span>':''}</span><span>${e(m.month.slice(5))}</span><small class="greenhouse-month-coverage">${e(m.state==='UNKNOWN'?'?':m.state==='PARTIAL'?'Частично':'')}</small>`,greenhouseRoute(f,{month:m.month}),`harvest-month ${m.month===f.month?'selected':''} ${value==null?'unknown':''}`);}).join('')}</div>${note(`Период: ${f.date_from} — ${f.date_to}. Месяцы вне периода не показаны. Пустой месяц означает отсутствие известного значения, а не нулевой урожай.`)}${selected?row('Выбранный месяц · '+selected.month,measure(monthValue(selected,f.metric),unit),greenhouseMonthCoverage(selected,f.metric))+link('Весь выбранный период',greenhouseRoute(f,{month:null}),'section-link'):''}`)+
 card(`<h2>Источник веса и цены</h2>${row('Точно распределено',measure(h.depot_kg.exact_value,'кг'))}${row('Оценочное распределение',measure(h.depot_kg.estimated_value,'кг'))}${row('Не распределено в связанных документах',measure(h.depot_kg.unallocated_value,'кг'),'Не включено в итог теплицы')}${row('Средневзвешенная цена',financeAmount(h.weighted_price_per_kg,f.currency+'/кг'))}${note(`Основание цены: ${measure(h.priced_kg,'кг')} и ${financeAmount(h.priced_amount,f.currency)}. Оценка не добавляется вторым урожаем.`)}`)+
 card(`<h2>Качество депо</h2>${(h.quality_rows||[]).map(q=>row(({HIGHEST:'Высшее',FIRST:'Первое',SECOND:'Второе',UNKNOWN:'Не определено'})[q.quality]||'Не определено',measure(q.net_weight_kg,'кг'),`${q.share_percent==null?'Доля неизвестна':harvestNumber(q.share_percent)+'%'} · ${financeAmount(q.weighted_price_per_kg,f.currency+'/кг')}`)).join('')}${note('Неопределённое качество остаётся в общем весе. Непроверенные названия не превращаются в сорт автоматически.')}`)+
 card(`<h2>${f.month?'Записи месяца '+e(f.month):'Записи выбранного периода'}</h2>${f.metric==='revenue'?note('Выручка и её источники только в '+f.currency+'. Документы других валют доступны в показателе веса.') : ''}${events.map(v=>eventLink(`<strong>${e(v.event_date)} · ${f.metric==='branches'?'Полевой срез':'Документ депо'}</strong><small>${e(greenhouseEventValue(v,f))}${v.estimate_revision_id?' · есть оценка':''}</small>`,f.metric==='branches'?'report':'depot',v.id,f)).join('')||note('В выбранном месяце и охвате источников нет.')}`);
}
function finance(g,f){const x=g.finance;return card(`<h2>Результат по учтённым затратам</h2>${row('Выручка',financeAmount(x.revenue,f.currency))}${row('Прямые затраты',financeAmount(x.exact_cost,f.currency))}${row('GENERAL · аналитическая доля',financeAmount(x.virtual_general_cost,f.currency),'Виртуальное распределение. Бухгалтерские проводки не меняются.')}${row('Все учтённые затраты',financeAmount(x.operating_cost,f.currency))}${row('Результат известной части',financeAmount(x.operating_result,f.currency))}${note('Оплаты показывают движение денег и не добавляют затраты второй раз. Банковские остатки относятся ко всему хозяйству.')}${link('Открыть существующий Finance',`money/result/${f.date_from}/${f.date_to}/${f.currency}/${f.greenhouse_id}/all`,'btn secondary')}`)+card(`<h2>Показатели на вес и площадь</h2>${row('Учтённые затраты на кг',financeAmount(x.cost_per_kg?.known_finance_cost_per_kg,f.currency+'/кг'),classification(x.cost_per_kg?.classification))}${areaView(g.area)}${row('Затраты на дёнюм',financeAmount(x.per_da?.operating_cost,f.currency+'/дёнюм'))}${note('Неизвестный знаменатель не заменяется нулём. Это не полная себестоимость.')}`)+card(`<h2>Экономические события → источник</h2>${(x.economic_events||[]).map(v=>`<article class="money-event"><h3>${e(v.source?.description||v.ledger_account_name||'Событие')}</h3>${row(v.event_date,financeAmount(v.selected_amount,v.currency),v.classification==='REVENUE'?'Выручка':'Затраты')}${financeSourceLinks(v.source,greenhouseRoute(f))}<details><summary>Основание принадлежности</summary>${(v.allocations||[]).filter(a=>a.greenhouse_id===g.id).map(a=>row(a.name||g.name,financeAmount(a.amount,v.currency),a.classification==='GENERAL_VIRTUAL'?'GENERAL · аналитическая доля':a.classification==='ESTIMATED'?'Оценка':'Прямая принадлежность')).join('')}</details></article>`).join('')||note('Нет признанных экономических событий выбранного периода.')}`);}
function work(g,f,dayData){const w=g.work,d=w.day_workers||{},requests=greenhouseRequestGroups(dayData?.requests||[],g.id,f),actuals=(dayData?.actuals||[]).filter(a=>(d.actual_ids||[]).includes(a.id));return card(`<div class="card-header"><h2>Дневные рабочие</h2>${link('Открыть все работы','day-workers','section-link')}</div>${row('Запрошено, человеко-дней',harvestNumber(d.requested_people_days))}${row('Одобрено в плане, человеко-дней',harvestNumber(d.planned_people_days))}${row('Сообщено полных человеко-дней',harvestNumber(d.reported_people_days))}${row('Принято владельцем, человеко-дней',harvestNumber(d.confirmed_people_days))}${row('Начислено в периоде',financeAmount(d.accrued_amount,f.currency),'Уже включено в Finance-затраты выше')}${row('Выплачено в периоде',financeAmount(d.paid_amount,f.currency),d.payment_allocation_unknown?'Платёж общей бригаде не распределён по теплицам':'По отдельным подтверждённым платежам')}${row('Текущий долг связанных документов',financeAmount(d.current_debt,f.currency),d.debt_allocation_unknown?'Остаток общего долга бригады не распределён по теплицам. Все даты; это не исторический остаток.':'Все даты; это не исторический остаток выбранного периода')}${note('Число человеко-дней не является числом уникальных людей. План, сообщение, принятый факт, начисление и оплата разделены.')}${attentionRows(w)}<h3>Заявки выбранного периода</h3>${requests.period.map(r=>eventLink(`<strong>${e(r.current_plan?.work||'Заявка')}</strong><small>${e(r.current_plan.start_date)} · ${e(r.worker_name||'Владелец')}</small>`,'day-request',r.id,f)).join('')||note('Датированных заявок в выбранном периоде нет.')}<h3>Без даты · отдельно от итогов периода</h3>${row('Запрошено без даты, человеко-дней',harvestNumber(d.undated_requested_people_days))}${row('Одобрено без даты, человеко-дней',harvestNumber(d.undated_planned_people_days))}${requests.undated.map(r=>eventLink(`<strong>${e(r.current_plan?.work||'Заявка')}</strong><small>Дата не указана · ${e(({PENDING:'Ожидает решения',APPROVED:'Одобрено',CLARIFICATION_REQUIRED:'Нужно уточнение',REJECTED:'Отклонено'})[r.state]||'Статус требует проверки')} · ${e(r.worker_name||'Владелец')}</small>`,'day-request',r.id,f)).join('')||note('Заявок без даты нет.')}${actuals.map(a=>eventLink(`<strong>${e(a.event_date)} · ${e(a.people)} человек</strong><small>${e(a.work)} · ${a.confirmation?'Принят владельцем':'Сообщён, требует проверки'}</small>`,'day-actual-detail',a.id,f)).join('')}${(d.documents||[]).map(doc=>eventLink(`<strong>Долг · ${e(doc.counterparty_name||'Проверенный кредитор')}</strong><small>${e(financeAmount(doc.remaining_amount,doc.currency))}</small>`,'money-document',doc.obligation_id,f)).join('')}`)+
 card(`<h2>Поручения и внимание</h2>${note('Текущий статус поручений. Просроченные и недатированные открытые работы видны отдельно от финансов периода.')}${(w.tasks||[]).map(t=>eventLink(`<strong>${e(t.title)}</strong><small>${e(t.planned_date||'Дата не назначена')} · ${e(t.status==='reported'?'Есть отчёт':t.status==='completed'?'Завершено':t.status==='cancelled'?'Отменено':'В работе')}</small>`,'worker-task',t.id,f)).join('')||note('Поручений в этом охвате нет.')}`)+
 card(`<h2>Внесения</h2>${(w.applications||[]).map(p=>eventLink(`<strong>${e(p.event_date)} · ${e(p.greenhouse_name||g.name)}</strong><small>${e(p.status||'План')}</small>`,'fertilizer-plan',p.id||p.plan_id,f)).join('')||note('Планов внесения в периоде нет.')}${link('Существующий календарь внесений',`fertilizer/${f.date_from}/${f.date_to}/${g.id}`,'btn secondary')}`);}
export function greenhouseDailyView(result,f,dayData=null){const selected=result.selected||result.greenhouses.find(g=>g.id===f.greenhouse_id),title=selected?.name||'Теплицы';return Header(title,`${f.date_from} — ${f.date_to} · ${f.currency}`)+`<div class="page-actions">${selected?link('Все теплицы',greenhouseRoute(f,{greenhouse_id:null}),'btn secondary'):link('На главную','home','btn secondary')}</div>`+greenhouseFilters(result,f)+(selected?`<nav class="greenhouse-tabs" aria-label="Разделы теплицы">${Object.entries(tabs).map(([key,label])=>link(label,greenhouseRoute(f,{tab:key}),key===f.tab?'active':'')).join('')}</nav>${f.tab==='overview'?overview(selected,f):f.tab==='harvest'?harvest(selected,f):f.tab==='finance'?finance(selected,f):work(selected,f,dayData)}`:`<div class="greenhouse-grid">${result.greenhouses.map(g=>link(`<span class="greenhouse-card-heading">${icon('leaf')}<strong>${e(g.name)}</strong>${icon('arrow')}</span>${row('Ветки поля',measure(g.harvest.branches.value,'веток'))}${row('Вес депо',measure(g.harvest.depot_kg.value,'кг'))}${row('Выручка',financeAmount(g.finance.revenue,f.currency))}${attentionRows(g.work)}`,greenhouseRoute(f,{greenhouse_id:g.id}),'card greenhouse-card greenhouse-tile')).join('')}</div>`)+card(`<details><summary>Полнота данных и время чтения</summary>${note(`Ответ сервера: ${result.snapshot_at}. Сезон: ${result.filters.season_start} — ${result.filters.season_end} (правая граница не включена).`)}${note('Дата периода выбирает события. Исторический срез «как было известно тогда» не поддерживается. Неполные источники не считаются нулевыми.')}${row('Нераспределённые затраты хозяйства',financeAmount(result.coverage?.unresolved_cost,f.currency))}${row('Нераспределённая выручка хозяйства',financeAmount(result.coverage?.unallocated_revenue,f.currency))}${row('Нераспределённый вес хозяйства',measure(result.coverage?.unallocated_depot_kg,'кг'))}${note('Нераспределённая часть относится к хозяйству и не начислена каждой теплице.')}${f.allocation!=='all'?note('Фильтр точности относится к урожаю. Финансы сохраняют все признанные экономические события.'):''}${(result.coverage?.day_workers_warnings||[]).map(x=>note(({PLAN_DATE_UNKNOWN:'Есть заявки без даты: они не включены в план периода.',ACTUAL_ALLOCATION_INCOMPLETE:'Есть факты с неполным распределением бригады.',FULL_DAY_UNRESOLVED:'Есть сообщения с неизвестным или неполным днём.'})[x]||x)).join('')}</details>`);}
